#include <bits/stdc++.h>
using namespace std;
int main(int c, char** v) { ifstream in(v[1]), out(v[2]); int n, m, k; in >> n >> m >> k; vector<array<long long,3>> e(m); for (auto& [a, b, w] : e) in >> a >> b >> w; auto dist = [&](vector<int> ids) { vector<long long> d(n + 1, LLONG_MAX / 4); d[1] = 0; for (int it = 0; it < n; it++) for (int i : ids) { auto [a, b, w] = e[i]; d[b] = min(d[b], d[a] + w); d[a] = min(d[a], d[b] + w); } return d; }; vector<int> all(m); iota(all.begin(), all.end(), 0); auto d = dist(all); int cnt; if (!(out >> cnt) || cnt < 0 || cnt > k) return 1; vector<int> ids; set<int> s; for (int i = 0; i < cnt; i++) { int id; if (!(out >> id) || id < 1 || id > m || !s.insert(id).second) return 1; ids.push_back(id - 1); } auto t = dist(ids); int good = 0; for (int x = 1; x <= n; x++) if (t[x] == d[x]) good++; return good == min(k + 1, n) ? 0 : 1; }
